@extends('layouts.app') @section('title','Peta Pelabuhan') @section('content')<div class="container-fluid"><div class="d-flex justify-content-between mb-4"><div><h3>Peta Pelabuhan Global</h3><p class="text-muted mb-0">{{ $ports->count() }} lokasi · Leaflet & OpenStreetMap</p></div><a href="{{ route('ports.index') }}" class="btn btn-outline-secondary">Daftar</a></div><div class="info-card"><div class="card-body p-0"><div id="portsMap" style="height:620px"></div></div></div></div>@endsection @push('styles')<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">@endpush @push('scripts')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const map=L.map('portsMap').setView([0,110],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const ports=@json($portMarkers);ports.filter(p=>p.lat||p.lng).forEach(p=>L.marker([p.lat,p.lng]).addTo(map).bindPopup(`<strong>${p.name}</strong><br>${p.country||''}<br><a href="${p.url}">Detail</a>`));</script>@endpush
